import clsx from 'clsx';
import React from 'react';

import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

// #region Typings
export type DataTableCellProps = WithChildren & StylingProps & DataTestId;
// #endregion Typings

/**
 * DataTable custom Cell renderer Wrapper.
 *
 * @returns Cell component
 */
export const Cell = (props: DataTableCellProps) => {
  const {
    children,
    style: consumerStyle,
    className: consumerClassName,
    'data-testid': dataTestId,
  } = props;

  return (
    <div
      className={clsx('strato-table-custom-cell-wrapper', consumerClassName)}
      style={consumerStyle}
      data-testid={dataTestId}
    >
      {children}
    </div>
  );
};

Cell['displayName'] = 'DataTable.Cell';
